import json
from pathlib import Path
inv=json.loads(Path('output/editorial-source-inventory.json').read_text(encoding='utf8')); surfaces={r['surfaceId']:r for r in inv['surfaces']}
changes={
'graduation-path.gp-1':{'graduatedLooksLike':'Use the checklist to prepare a program-specific account of access barriers, people to involve, responsibilities and questions for review. This preparation supports a discussion with the people responsible for the work; it does not establish that a design is ready or remove required review.','privacy':'Leave out client names, case IDs and identifying accounts. Use general descriptions in the published checklist, and keep any completed working file according to the information rules for your work.','step0Guidance':'Ask about the proposed design, then examine the response’s sources and limits. Record the equity and access questions you still need to investigate while choices remain open.','step3Guidance':'Use the checklist to record what is known, what remains uncertain and who needs to contribute. Keep names and case details out of the working notes.'},
'graduation-path.gp-2':{'graduatedLooksLike':'Prepare a record of the proposed change, its possible effects, access needs, sources and follow-up responsibilities. Use it to support review with the policy owner and other responsible offices. A completed checklist does not resolve a conflict between sources or authorize a change.','step0Guidance':'Ask about plain language, access and service processes. Compare the response with the policy or rule being considered, and record questions that require an official source or the policy owner’s judgment.','step5Guidance':'Confirm who must review or authorize the proposed change. If official sources conflict or their meaning is uncertain, take the specific question and source references to the responsible office before proceeding.'},
'graduation-path.gp-3':{'graduatedLooksLike':'Prepare an engagement plan that connects community context with the decision people can influence. Identify participation supports, the people and partners to involve, unresolved questions and how you will report back. Review relevant briefs as preparation for direct engagement; reading a brief does not establish a community’s agreement or an individual’s preferences.','step1Guidance':'Read the relevant community briefs to understand context and develop questions about participation and access. Note which sources informed the plan and what still needs to be learned directly from participants. Do not treat a brief as a profile of the people you will meet.'}
}
rows=[]
for target,fs in changes.items():
 r=surfaces[target];rows.append({'target':target,'kind':'surface','route':r['route'],'original':r['values'],'changes':[{'path':[k],'before':r['values'][k],'after':v,'reason':'Replace unsupported independence/completion claims with useful preparation, individual inquiry and clear review authority; align to published read/download route.'} for k,v in fs.items()]})
Path('output/practice-path-first-revisions.json').write_text(json.dumps({'records':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
